def apply(all_content, about, faq, taglines):
    for lang, pages in all_content.items():
        p = PURPOSE[lang]
        pages['index']['hero_lede'] = p['hero']
        pages['index']['desc'] = p['mission']
        taglines[lang] = p['mission']
        about['desc'][lang] = p['mission']
        about['header_title'][lang] = p['title']
        about['header_lede'][lang] = p['mission']
        about['principles_title'][lang] = p['principles_title']
        about['principles'][lang] = p['principles']
        about['contribute_title'][lang] = {'zh':'作品与记录', 'en':'Works and records', 'es':'Obras y registros', 'pt':'Obras e registros'}[lang]
        about['contribute'][lang] = [(pages['writing']['header_title'], p['writing']), (pages['heartbeat']['header_title'], p['heartbeat'])]
        pages['writing']['header_lede'] = p['writing']
        pages['writing']['desc'] = p['writing']
        pages['heartbeat'].update(desc=p['heartbeat'], header_lede=p['heartbeat'], about=p['method'])
        for i, work in enumerate(pages['writing']['works']):
            if work[0].startswith('DAILY'):
                pages['writing']['works'][i] = (*work[:3], [p['heartbeat'], p['method']], p['record'])
        faq[lang][0] = (faq[lang][0][0], p['mission'])
        faq[lang][3] = (faq[lang][3][0], p['faq'])
